# Reference GRIM verdicts for gaply_core's grim_mean and grim_percent
# (Phase 1, Step 6).
#
# Run with the R that has the reference packages, by its full path:
#
#   /usr/local/bin/Rscript make_grim_fixtures.R
#
# Writes grim_fixtures.csv next to this script. Columns: x (the printed value,
# trailing zeros kept), n, items, percent, consistent. `consistent` is
# scrutiny::grim(x, n, items, percent) at its defaults (rounding =
# "up_or_down"), which accepts rounding up or down at the half.
#
# The grid, about 5,000 rows, spread evenly by a fixed stride through each
# full cartesian product (a stride coprime to the inner dimension, so every
# value and every n recur):
#   1. two-decimal means "1.00".."7.00", n 5..99, items 1       (stride 19)
#   2. the same means, n 5..33, items 2 and 3 (n * items < 100)  (stride 35)
#   3. whole-number percentages 1..99, n 5..99, percent = TRUE   (stride 10)

suppressPackageStartupMessages(library(scrutiny))

script_dir <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f) == 1) dirname(normalizePath(f)) else getwd()
})

means <- sprintf("%.2f", seq(100, 700) / 100)
pick <- function(grid, stride) grid[seq(1, nrow(grid), by = stride), ]

g1 <- expand.grid(x = means, n = 5:99, items = 1L, stringsAsFactors = FALSE)
g2 <- expand.grid(x = means, n = 5:33, items = 2:3, stringsAsFactors = FALSE)
g3 <- expand.grid(x = as.character(1:99), n = 5:99, items = 1L, stringsAsFactors = FALSE)
g1 <- pick(g1, 19); g1$percent <- FALSE
g2 <- pick(g2, 35); g2$percent <- FALSE
g3 <- pick(g3, 10); g3$percent <- TRUE
rows <- rbind(g1, g2, g3)

rows$consistent <- mapply(
  function(x, n, items, percent) grim(x, n, items = items, percent = percent),
  rows$x, rows$n, rows$items, rows$percent
)

out <- file.path(script_dir, "grim_fixtures.csv")
con <- file(out, "w")
writeLines(c(
  "# Reference GRIM verdicts for gaply_core's grim_mean and grim_percent.",
  "# Generated by /usr/local/bin/Rscript make_grim_fixtures.R (do not edit by hand).",
  paste0("# ", R.version.string),
  paste0("# scrutiny ", as.character(packageVersion("scrutiny")),
         "; consistent = scrutiny::grim(x, n, items, percent), rounding up_or_down"),
  "x,n,items,percent,consistent"
), con)
writeLines(sprintf("%s,%d,%d,%s,%s", rows$x, rows$n, rows$items,
                   ifelse(rows$percent, "TRUE", "FALSE"),
                   ifelse(rows$consistent, "TRUE", "FALSE")), con)
close(con)
cat(sprintf("wrote %d rows to %s\n", nrow(rows), out))
